/**  Which model a sub agent runs (18 §5). */
export type AgentModel = 
/**  The parent's own model. The default, and the only one that needs no configuration. */
{ kind: "inherit" } | 
/**  Let the parent choose from the rules the user wrote, which are shown to it as a menu. */
{ kind: "rules" } | 
/**  One model, named here and not up for discussion. */
{ kind: "named"; model: ModelRef };

/**  One entry of the library (18 §3). */
export type AgentType = {
	/**  The slug the model names in a call, and the id of the row. */
	id: string,
	name: string,
	/**  One line, read by the **parent** model when it chooses between types. */
	description: string,
	/**  The system prompt fragment the sub agent runs under. */
	instructions: string,
	model: AgentModel,
	/**  The namespaces it may use. [`INHERIT`] stands for the parent chat's own list. */
	connectors: string[],
	/**  `None` means the parent chat's mode, whatever that is. */
	mode: Mode | null,
	guard: boolean | null,
	/**  Whether it may change files in the session's folders, or only read them. */
	write_files: boolean,
	/**  Whether the user's memories reach its prompt, and whether it may load skills (12). */
	memory: boolean,
	skills: boolean,
	/**  The fields the parent may set in the call. Everything else is the type's own. */
	open: OpenField[],
	/**  Shipped with Gantry. Editable; **Reset** puts the original back. */
	builtin: boolean,
	enabled: boolean,
};

/**  The sub-agent library changed: one was written, reset, deleted or switched (18 §3). */
export type AgentTypesChanged = null;

/**
 *  Facts about the running application, returned by the `app_info` command.
 * 
 *  The first typed value to cross the IPC boundary; the bindings pipeline is proven on it.
 */
export type AppInfo = {
	/**  Application version from `Cargo.toml`. */
	version: string,
	/**  Operating system family: `macos`, `windows` or `linux`. */
	os: string,
	/**  CPU architecture, e.g. `aarch64` or `x86_64`. */
	arch: string,
	/**  The application data directory (database, blobs, skills, logs). */
	data_dir: string,
	/**  The log directory. */
	log_dir: string,
	/**  Whether this is a debug build. */
	debug: boolean,
};

export type AppearanceSettings = {
	theme?: Theme,
	density?: Density,
};

/**
 *  One argument a permission card offers to change, with what to change it to.
 * 
 *  The case it was built for is `media__generate`'s model. The card already names the model that
 *  is about to spend money; showing the name and not letting the user change it is the one
 *  unhelpful arrangement — deny and re-ask is the only way through, and it costs a whole round
 *  trip through the chat model to say "use that one instead".
 */
export type ArgChoice = {
	/**  The argument's name, as the tool's own schema spells it. */
	key: string,
	/**  What to call it on the card: "Model", not `model`. */
	label: string,
	/**
	 *  The value the call will use unless the user changes it. Already resolved: what the
	 *  connector *would* do, not what the model literally typed, so the card shows the thing
	 *  that is about to happen.
	 */
	value: string | null,
	/**  What it may be changed to. A choice with none is shown but not editable. */
	options: ChoiceOption[],
	/**
	 *  Why the value is not what the model asked for, when it is not — a model it named that
	 *  this machine does not have, a default that stood in. Shown on the card as a warning,
	 *  because a silent substitution is the one thing a card like this must not do.
	 */
	note: string | null,
};

/**
 *  A predicate on the call's arguments (04 §8). The path and command forms wait for the tools
 *  that produce them; both match by prefix on the named argument when it is a string.
 */
export type ArgScope = { kind: "path_prefix"; prefix: string } | { kind: "command_prefix"; prefix: string };

/**  An artifact with the content of one version and its history, as the panel reads it. */
export type ArtifactContent = {
	artifact: ArtifactDto,
	version: number,
	content: string,
	versions: ArtifactVersionDto[],
};

/**  The `artifacts` row. */
export type ArtifactDto = {
	id: ArtifactId,
	chat_id: ChatId,
	project_id: ProjectId | null,
	/**  `markdown`, `code`, `html`, `svg`, `mermaid`, `react`. */
	type: string,
	title: string,
	language: string | null,
	summary: string | null,
	current_version: number,
	created_by_message_id: MessageId | null,
	created_at: number,
	updated_at: number,
};

/**  A versioned piece of content shown beside the chat. */
export type ArtifactId = string;

/**  One `artifact_versions` row without its content. */
export type ArtifactVersionDto = {
	artifact_id: ArtifactId,
	version: number,
	source: VersionSource,
	tool_call_id: string | null,
	message_id: MessageId | null,
	note: string | null,
	size: number,
	created_at: number,
};

/**  A user edit or restore made a new artifact version outside a turn (13 §10). */
export type ArtifactsChanged = {
	chat_id: ChatId,
	artifact_id: ArtifactId,
};

